  const [reportCategory, setReportCategory] = useState("Diagram issue"); const [reportNote, setReportNote] = useState("");
  const [sequenceText,setSequenceText]=useState(""); const [sequenceResult,setSequenceResult]=useState(""); const [sequenceRoute,setSequenceRoute]=useState<ChordLibraryItem[]>([]);
  const [blindMap,setBlindMap]=useState<readonly [0|1,0|1]>([0,1]); const [blindVote,setBlindVote]=useState<"A"|"B"|null>(null); const [blindBusy,setBlindBusy]=useState(false); const [blindError,setBlindError]=useState("");
  const [blindPair,setBlindPair]=useState("");
  const blindSignature=`${selected.id}|${comparison?.id??""}|${tuning.label}|${tuning.semitoneOffsets.join(",")}|${capo}`;
  const [bassLock, setBassLock] = useState<number | null>(null); const [melodyLock, setMelodyLock] = useState<number | null>(null);
  const [intentionalOmissions,setIntentionalOmissions]=useState<number[]>([]); const [melodyTone,setMelodyTone]=useState<number|null>(null);
  const [collections,setCollections]=useState<ChordCollection[]>([]); const [collectionName,setCollectionName]=useState(""); const [activeCollectionId,setActiveCollectionId]=useState("");
  const [draftFrets,setDraftFrets]=useState<number[]>(selected.chord.frets); const [draftFingers,setDraftFingers]=useState<Array<1|2|3|4|null>>(selected.chord.fingers??Array(6).fill(null)); const [draftRoot,setDraftRoot]=useState(selected.root); const [draftQuality,setDraftQuality]=useState(selected.quality); const [draftInversion,setDraftInversion]=useState<"standard"|"inverted">(selected.inversion);
  const [draftLabel,setDraftLabel]=useState(selected.chord.name);
  const [overrideHistory,setOverrideHistory]=useState<ChordOverride[]>([]);
  const [localShapes,setLocalShapes]=useState<LocalChordShape[]>([]); const [transitionLog,setTransitionLog]=useState<TransitionEvent[]>([]);
  const [customFrets,setCustomFrets]=useState<number[]>(Array(6).fill(-1)); const [customRoot,setCustomRoot]=useState("C"); const [customQuality,setCustomQuality]=useState("major"); const [midiRawCounts,setMidiRawCounts]=useState<Record<number,number>>({}); const [midiStatus,setMidiStatus]=useState("MIDI is disconnected."); const midiCleanup=useRef<(() => void)|null>(null);
  const [backupStatus,setBackupStatus]=useState(""); const [pendingBackup,setPendingBackup]=useState<unknown>(null); const importFileRef=useRef<HTMLInputElement|null>(null); const [maintenanceRows,setMaintenanceRows]=useState<Array<{entry:ChordLibraryItem;kind:string;detail:string}>>([]); const [customMidiEnabled,setCustomMidiEnabled]=useState(false);
  const [coverageReport,setCoverageReport]=useState<ReturnType<typeof chordLibraryCoverage>|null>(null);
  const [correctionRows,setCorrectionRows]=useState<ReturnType<typeof suggestVoicingCorrections>>([]);
  const blindTimerRef=useRef<number|null>(null); const reportTimerRef=useRef<number|null>(null); const reportUrlRef=useRef<string|null>(null);
  useEffect(() => {
    try {
      const layout: unknown = JSON.parse(localStorage.getItem(PANEL_KEY) ?? "null");
      if (layout && typeof layout === "object" && !Array.isArray(layout)) {
        const v = layout as {order?:unknown;hidden?:unknown};
        if (Array.isArray(v.order)) { const order = v.order.filter((id): id is string => typeof id === "string" && PANEL_IDS.includes(id)); setPanelOrder([...new Set([...order, ...PANEL_IDS])]); }
        if (Array.isArray(v.hidden)) setHiddenPanels([...new Set(v.hidden.filter((id): id is string => typeof id === "string" && PANEL_IDS.includes(id))) ]);
      }
      const value: unknown = JSON.parse(localStorage.getItem(TODAY_KEY) ?? "[]");
      if (Array.isArray(value)) setTodayIds([...new Set(value.filter((id): id is string => typeof id === "string" && CHORD_ID_SET.has(id)))].slice(0, MAX_PINNED));
      setCollections(validateChordCollections(JSON.parse(localStorage.getItem("chord-hero-user-collections-v1") ?? "[]")));
      setLocalShapes(validateLocalChordShapes(JSON.parse(localStorage.getItem(LOCAL_CHORDS_KEY) ?? "[]")));
      setTransitionLog(validateTransitionLog(JSON.parse(localStorage.getItem(TRANSITION_LOG_KEY) ?? "[]")));
    } catch { setTodayIds([]); }
    setHydrated(true);
  }, []);
  useEffect(() => { if (hydrated) { try { localStorage.setItem(PANEL_KEY, JSON.stringify({ order: panelOrder, hidden: hiddenPanels })); } catch { /* Keep preferences in memory if storage is unavailable. */ } } }, [hydrated, panelOrder, hiddenPanels]);
  useEffect(() => { if (hydrated) { try { localStorage.setItem(TODAY_KEY, JSON.stringify(todayIds.slice(0, MAX_PINNED))); } catch { /* Keep the in-memory set usable when storage is unavailable. */ } } }, [hydrated, todayIds]);
  useEffect(() => { if (hydrated) { try { localStorage.setItem("chord-hero-user-collections-v1", JSON.stringify(validateChordCollections(collections))); } catch { /* Keep this session usable if storage is unavailable. */ } } }, [hydrated, collections]);
  useEffect(() => { if (hydrated) { try { localStorage.setItem(LOCAL_CHORDS_KEY, JSON.stringify(validateLocalChordShapes(localShapes))); } catch { /* Local editing remains available for this session. */ } } }, [hydrated, localShapes]);
  useEffect(() => { if (hydrated) { try { localStorage.setItem(TRANSITION_LOG_KEY, JSON.stringify(validateTransitionLog(transitionLog))); } catch { /* Keep this session usable if storage is unavailable. */ } } }, [hydrated, transitionLog]);
  useEffect(() => { setDraftFrets(override?.chord.frets ?? selected.chord.frets); setDraftFingers(override?.chord.fingers ?? selected.chord.fingers ?? Array(6).fill(null)); setDraftRoot(override?.root ?? selected.root); setDraftQuality(override?.quality ?? selected.quality); setDraftInversion(override?.inversion ?? selected.inversion); setDraftLabel(override?.displayLabel ?? selected.chord.name); }, [selected.id, selected.chord.frets, selected.chord.fingers, selected.chord.name, selected.root, selected.quality, selected.inversion, override]);
  useEffect(()=>{try{const value=JSON.parse(localStorage.getItem(`chord-hero-override-history-${selected.id}`)??"[]");setOverrideHistory(Array.isArray(value)?value.slice(-10).flatMap(item=>{const valid=validateChordOverrides({[selected.id]:item})[selected.id];return valid?[valid]:[]}):[]);}catch{setOverrideHistory([]);}},[selected.id]);
  useEffect(()=>{if(blindActive&&blindPair!==blindSignature){onBlindActiveChange(false);setBlindVote(null);setBlindError("");}},[blindActive,blindPair,blindSignature,onBlindActiveChange]);
  useEffect(()=>()=>{if(blindTimerRef.current!==null)window.clearTimeout(blindTimerRef.current);if(reportTimerRef.current!==null)window.clearTimeout(reportTimerRef.current);if(reportUrlRef.current)URL.revokeObjectURL(reportUrlRef.current);},[]);
  useEffect(()=>()=>midiCleanup.current?.(),[]);
  useEffect(()=>{setIntentionalOmissions([]);},[selected.id,tuning.label,capo]);

  const toneRows = useMemo(() => chordTones(selected, tuning, capo, spelling), [selected, tuning, capo, spelling]);
  const audit = useMemo(() => completenessAudit(selected, tuning, capo, intentionalOmissions, spelling), [selected, tuning, capo, intentionalOmissions, spelling]);
  const sounding = useMemo(() => soundingSummary(selected, tuning, capo, spelling), [selected, tuning, capo, spelling]);
  const equivalent = useMemo(() => nearestEquivalent(selected, entries, tuning, capo), [selected, entries, tuning, capo]);
  const reviews = useMemo(() => reviewQueue(CHORD_LIBRARY, stats), [stats]);
  const substitutions = useMemo(() => functionalAlternatives(selected, CHORD_LIBRARY, harmonyKey, mode).map(item => { const from=new Set(soundingSummary(selected,tuning,capo,spelling).pitches), to=new Set(soundingSummary(item.entry,tuning,capo,spelling).pitches); return { ...item, difficulty: (item.entry.difficultyTags.includes("barre") ? "barre" : "no barre") + (item.entry.difficultyTags.includes("stretch") ? ", stretch" : ", compact reach"), transition: scoreTransition(selected.chord, item.entry.chord).score, shared:[...from].filter(n=>to.has(n)), lost:[...from].filter(n=>!to.has(n)), added:[...to].filter(n=>!from.has(n)) }; }).sort((a, b) => a.transition - b.transition).slice(0, 6), [harmonyKey, mode, selected, tuning, capo, spelling]);
  const transitions = useMemo(() => {
    const bestByIdentity = new Map<string, { entry: ChordLibraryItem; score: number }>();
    CHORD_LIBRARY.filter(e => e.id !== selected.id && (e.root !== selected.root || e.quality !== selected.quality)).forEach(entry => {
      const score = transitionEstimate(selected, entry, genre, harmonyKey, mode, tempo), identity = `${entry.root}:${entry.quality}`;
      if (!bestByIdentity.has(identity) || score > bestByIdentity.get(identity)!.score) bestByIdentity.set(identity, { entry, score });
    });
    return [...bestByIdentity.values()].sort((a, b) => b.score - a.score).slice(0, 5);
  }, [genre, harmonyKey, mode, selected, tempo]);
  const visibleByFret = useMemo(() => {
    const min = minFret === "" ? null : Number(minFret), max = maxFret === "" ? null : Number(maxFret);
    if (min !== null && max !== null && min > max) return [];
    return CHORD_LIBRARY.filter(e => e.chord.frets.some(f => f >= 0) && e.chord.frets.every(f => f < 0 || ((min === null || f === 0 || f >= min) && (max === null || f <= max)))).slice(0, 12);
  }, [maxFret, minFret]);
  const pitchMatches = useMemo(() => CHORD_LIBRARY.filter(entry => {
    if (entry.chord.frets.length !== 6 || tuning.semitoneOffsets.length !== 6) return false;
    const notes = entry.chord.frets.flatMap((f,i)=>f<0?[]:[40+[0,5,10,15,19,24][i]+(tuning.semitoneOffsets[i]??0)+f+capo]);
    return notes.length > 0 && (bassLock === null || Math.min(...notes)%12 === bassLock) && (melodyLock === null || Math.max(...notes)%12 === melodyLock);
  }).slice(0,8), [bassLock,melodyLock,tuning,capo]);
  const steps = selected.chord.frets.flatMap((fret, i) => fret > 0 ? [{ string: 6 - i, fret, finger: selected.chord.fingers?.[i] }] : []);
  const setPanelHidden = (id: string) => setHiddenPanels(v => v.includes(id) ? v.filter(x => x !== id) : [...v, id]);
  const movePanel = (id: string, delta: number) => setPanelOrder(v => { const i=v.indexOf(id), j=Math.max(0,Math.min(v.length-1,i+delta)); const n=[...v]; n.splice(i,1); n.splice(j,0,id); return n; });
  const panelLabel = (id:string) => ({intent:"Voicing intent",equivalent:"Alternate tuning",tones:"Chord-tone ear check",placement:"Slow placement",transition:"Transition estimate",alternatives:"Functional alternatives",fret:"Fret-position filter",leading:"Voice-leading path",review:"Review queue",audit:"Completeness audit & report",pitchLock:"Bass / melody locks",progression:"Progression optimizer",blind:"Blind A/B listening",omissions:"Intentional omissions",tradeoff:"Substitution tone tradeoffs",editor:"Local chord-data editor",score:"Voicing score",collections:"My chord collections",progress:"Progress snapshot",quality:"Library data quality",maintenance:"Data maintenance queue",provenance:"Chord provenance and confidence",backup:"Local backup / restore",transitionPractice:"Observed transition practice",fingerInspector:"Finger movement inspector",customShape:"Custom shape entry"}[id] ?? id);
  const report = () => {
    const record = { chordId:selected.id, frets:selected.chord.frets, fingers:selected.chord.fingers ?? [], tuning:tuning.label, capo, category:reportCategory.slice(0,48), note:reportNote.trim().slice(0,2000), timestamp:new Date().toISOString() };
    try { const prior=JSON.parse(localStorage.getItem("chord-hero-diagram-reports-v1")??"[]"); const rows=Array.isArray(prior)?prior.filter(x=>x&&typeof x==="object").slice(-19):[]; localStorage.setItem("chord-hero-diagram-reports-v1",JSON.stringify([...rows,record])); } catch { /* Export remains available when local storage is blocked or full. */ }
    const url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:"application/json"})), a=document.createElement("a"); reportUrlRef.current=url; a.href=url; a.download=`chord-diagram-report-${selected.id}.json`; a.click(); if(reportTimerRef.current!==null)window.clearTimeout(reportTimerRef.current); reportTimerRef.current=window.setTimeout(()=>{URL.revokeObjectURL(url);reportUrlRef.current=null;},1000);
  };
  const startBlind=()=>{if(!comparison)return;const first=Math.random()<.5?0:1;setBlindMap([first,(1-first) as 0|1]);setBlindVote(null);setBlindError("");setBlindPair(blindSignature);onBlindActiveChange(true);};
  const playBlind=async(letter:"A"|"B")=>{if(blindBusy||blindVote||!comparison)return;setBlindBusy(true);setBlindError("");try{const idx=blindMap[letter==="A"?0:1];await onPlayChord(idx===0?selected:comparison);}catch(e){setBlindError(e instanceof Error?e.message:"Audio preview failed. Please retry.");}finally{if(blindTimerRef.current!==null)window.clearTimeout(blindTimerRef.current);blindTimerRef.current=window.setTimeout(()=>{setBlindBusy(false);blindTimerRef.current=null;},2000);}};
