  const todayEntries = todayIds.map(id => CHORD_BY_ID.get(id)).filter((e): e is ChordLibraryItem => Boolean(e));
  const qualityAudit = useMemo(() => auditChordLibrary(entries), [entries]);
  const selectedValidation = useMemo(() => validateSoundingHarmony(selected, tuning, capo), [selected, tuning, capo]);
